// And groups predicates with the AND operator between them.
func And(predicates ...predicate.PolicyDecisionSnapshot) predicate.PolicyDecisionSnapshot {
	return predicate.PolicyDecisionSnapshot(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
